package cn.yueji.balance;

import java.time.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class V4711RulesTest {
    LocalDateTime at(String value){return LocalDateTime.parse(value);}
    Ledger.Data data(){Ledger.Data d=new Ledger.Data();for(int i=1;i<=2;i++){Ledger.Account a=new Ledger.Account(i,i==1?"支付宝":"微信",i==1?"支付宝":"微信");a.created=at("2026-09-30T20:00");a.opening=i==1?1000000:500000;d.accounts.add(a);MonthLedger.updateAccount(d,i,a.created,a.opening);}return d;}
    Ledger.Snapshot row(Ledger.Data d,String time){return d.snapshots.stream().filter(s->s.at.equals(at(time))).findFirst().get();}
    Ledger.Entry entry(Ledger.Data d,String kind,long amount,String time,long account,boolean linked){Ledger.Entry e=new Ledger.Entry(d.nextId(),Ledger.INCOME.equals(kind),amount,at(time),Ledger.INCOME.equals(kind)?"工资":"房租","",account);e.kind=kind;e.category="其他";e.cashLinked=linked;e.nearestCash=true;d.entries.add(e);return e;}
    Ledger.Report october(Ledger.Data d){return Ledger.month(d,YearMonth.of(2026,10));}
    @Test public void transferCreatesTwoBalancesWithSameSourceAndNoIncomeExpense(){Ledger.Data d=data();Ledger.Transfer t=TransferLedger.save(d,0,1,2,150000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);assertEquals(850000,d.balance(d.accounts.get(0)));assertEquals(650000,d.balance(d.accounts.get(1)));assertEquals(1500000,d.total());assertEquals(0,Ledger.income(d,2026));assertTrue(d.entries.isEmpty());assertEquals(0,october(d).expense);Ledger.Snapshot s=row(d,"2026-10-05T15:00");for(long id:new long[]{1,2})assertTrue(AccountRecords.note(s,id).contains(TransferLedger.description(d,t)));}
    @Test public void transferEditAndDeleteRebuildBothSides(){Ledger.Data d=data();Ledger.Transfer t=TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);TransferLedger.save(d,t.id,2,1,50000,at("2026-10-06T15:00"),"更正");LedgerStore.validate(d);assertFalse(d.snapshots.stream().anyMatch(s->s.at.equals(at("2026-10-05T15:00"))));assertEquals(1050000,d.balance(d.accounts.get(0)));assertEquals(450000,d.balance(d.accounts.get(1)));d.transfers.clear();LedgerStore.validate(d);assertEquals(1000000,d.balance(d.accounts.get(0)));assertEquals(500000,d.balance(d.accounts.get(1)));assertEquals(1,d.snapshots.size());}
    @Test public void sameTimeTransfersMergeAndConserveTotal(){Ledger.Data d=data();TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"");TransferLedger.save(d,0,2,1,30000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);assertEquals(930000,d.balance(d.accounts.get(0)));assertEquals(570000,d.balance(d.accounts.get(1)));assertEquals(2,d.snapshots.size());assertEquals(0,october(d).expense);}
    @Test public void failedTransferCandidateDoesNotModifyOriginal(){Ledger.Data original=data(),candidate=LedgerStore.decode(LedgerStore.encode(original));String before=LedgerStore.encode(original);TransferLedger.save(candidate,0,1,2,1000001,at("2026-10-05T15:00"),"");try{LedgerStore.validate(candidate);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("余额"));}assertEquals(before,LedgerStore.encode(original));}
    @Test(expected=IllegalArgumentException.class) public void transferRejectsSameAccount(){TransferLedger.save(data(),0,1,1,1,at("2026-10-05T15:00"),"");}
    @Test(expected=IllegalArgumentException.class) public void transferRejectsUnselectedAccount(){TransferLedger.save(data(),0,1,0,1,at("2026-10-05T15:00"),"");}
    @Test(expected=IllegalArgumentException.class) public void transferRejectsFuture(){TransferLedger.save(data(),0,1,2,1,LocalDateTime.now().plusDays(1),"");}
    @Test(expected=IllegalArgumentException.class) public void transferRejectsZero(){TransferLedger.save(data(),0,1,2,0,at("2026-10-05T15:00"),"");}
    @Test(expected=IllegalArgumentException.class) public void transferRequiresKnownSourceBaseline(){Ledger.Data d=data();AccountRecords.delete(d,1,d.accounts.get(0).created);TransferLedger.save(d,0,1,2,1,at("2026-10-05T15:00"),"");LedgerStore.validate(d);}
    @Test public void manualNotesArePerAccountAndPreserveExplicitEmpty(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-05T15:00"),900000);MonthLedger.updateAccount(d,2,at("2026-10-05T15:00"),490000,"微信核对");LedgerStore.validate(d);Ledger.Snapshot s=row(d,"2026-10-05T15:00");assertEquals("用户手动更新余额",AccountRecords.note(s,1));assertEquals("微信核对",AccountRecords.note(s,2));AccountRecords.edit(d,1,s.at,s.at,880000,"");LedgerStore.validate(d);assertEquals("",AccountRecords.note(s,1));assertEquals("微信核对",AccountRecords.note(s,2));}
    @Test public void nearestFutureAnchorBackCalculatesWithoutDoubleDebit(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-11-01T10:00"),500000);entry(d,Ledger.LARGE,150000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);Ledger.Snapshot s=row(d,"2026-10-30T10:00");assertEquals(Long.valueOf(500000),s.balances.get(1L));assertTrue(AccountRecords.note(s,1).contains("后续实测逆推"));assertTrue(AccountRecords.note(s,1).contains("大宗支出：房租"));assertEquals(Long.valueOf(500000),row(d,"2026-11-01T10:00").balances.get(1L));assertEquals(500000,october(d).expense);assertTrue(october(d).estimated);assertEquals(0,Ledger.month(d,YearMonth.of(2026,11)).expense);}
    @Test public void nearestFutureRemovesKnownSubsequentIncome(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),500000);entry(d,Ledger.INCOME,50000,"2026-10-31T11:00",1,true);entry(d,Ledger.LARGE,150000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);assertEquals(Long.valueOf(450000),row(d,"2026-10-30T10:00").balances.get(1L));assertEquals(550000,october(d).expense);assertFalse(october(d).estimated);}
    @Test public void nearestPreviousAnchorAddsOrDeductsOnlyOnce(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-29T10:00"),800000);entry(d,Ledger.LARGE,150000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);assertEquals(650000,d.balance(d.accounts.get(0)));assertTrue(AccountRecords.note(row(d,"2026-10-30T10:00"),1).contains("之前实测正推"));}
    @Test public void equalDistancePrefersEarlierRealAnchor(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-29T12:00"),800000);MonthLedger.updateAccount(d,1,at("2026-10-31T12:00"),500000);entry(d,Ledger.LARGE,150000,"2026-10-30T12:00",1,true);LedgerStore.validate(d);assertEquals(Long.valueOf(650000),row(d,"2026-10-30T12:00").balances.get(1L));}
    @Test public void nearestIncomeDoesNotAddItAgainToFuturePostBalance(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-11-01T10:00"),1000000);entry(d,Ledger.INCOME,200000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);assertEquals(Long.valueOf(1000000),row(d,"2026-10-30T10:00").balances.get(1L));assertEquals(200000,october(d).expense);assertEquals(1000000,d.balance(d.accounts.get(0)));}
    @Test public void derivedRowsNeverBecomeTheirOwnReferenceAndRebuildIsIdempotent(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),500000);entry(d,Ledger.INCOME,50000,"2026-10-29T11:00",1,true);entry(d,Ledger.LARGE,150000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);String once=LedgerStore.encode(d);LedgerStore.validate(d);assertEquals(once,LedgerStore.encode(d));assertTrue(AccountRecords.note(row(d,"2026-10-30T10:00"),1).contains("2026/10/31 20:00"));}
    @Test public void sameInstantManualValueWinsButShowsSource(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-30T10:00"),500000,"核对值");entry(d,Ledger.INCOME,50000,"2026-10-30T10:00",1,true);LedgerStore.validate(d);Ledger.Snapshot s=row(d,"2026-10-30T10:00");assertEquals(Long.valueOf(500000),s.balances.get(1L));assertTrue(AccountRecords.note(s,1).contains("核对值"));assertTrue(AccountRecords.note(s,1).contains("收入：工资"));assertFalse(s.cashGenerated);assertEquals(550000,october(d).expense);}
    @Test public void uncheckedExpenseDoesNotChangeBalancesOrDoubleCount(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);entry(d,Ledger.LARGE,100000,"2026-10-10T10:00",0,false);LedgerStore.validate(d);assertEquals(700000,d.balance(d.accounts.get(0)));assertEquals(2,d.snapshots.size());assertEquals(300000,october(d).expense);}
    @Test public void uncheckedUnassignedIncomeStillAdjustsCoveredMonth(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);entry(d,Ledger.INCOME,100000,"2026-10-10T10:00",0,false);LedgerStore.validate(d);assertEquals(2,d.snapshots.size());assertEquals(400000,october(d).expense);assertEquals(100000,Ledger.income(d,YearMonth.of(2026,10)));}
    @Test public void previousMonthEndpointIncludesConsumptionBeforeFirstCurrentUpdate(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-01T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);MonthLedger.updateAccount(d,2,at("2026-10-31T20:00"),450000);assertEquals(350000,october(d).expense);assertEquals(2,MonthLedger.calculate(d,YearMonth.of(2026,10)).changes.size());assertTrue(october(d).boundaryWarning);}
    @Test public void incomeMustBeAddedBackToOpeningMinusClosing(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);entry(d,Ledger.INCOME,100000,"2026-10-10T10:00",1,false);assertEquals(400000,october(d).expense);}
    @Test public void priorMonthIncomeAfterOldBaselineIsNotAssignedToCurrentMonth(){Ledger.Data d=data();entry(d,Ledger.INCOME,100000,"2026-09-30T21:00",1,false);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),1000000);assertEquals(0,october(d).expense);}
    @Test public void missingEntirePriorMonthDoesNotAllocateMultiMonthDifference(){Ledger.Data d=data();d.snapshots.clear();for(Ledger.Account a:d.accounts)a.created=at("2026-07-01T00:00");MonthLedger.updateAccount(d,1,at("2026-10-10T10:00"),900000);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),800000);assertEquals(100000,october(d).expense);assertFalse(october(d).baseline);}
    @Test public void noCurrentObservationDoesNotInventMonthlyZero(){Ledger.Data d=data();assertFalse(october(d).hasData());}
    @Test public void missingCurrentAccountIsExplicitlyPartialNotACompleteMonth(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);Ledger.Report r=october(d);assertEquals(300000,r.expense);assertTrue(r.incomplete);assertFalse(r.hasDaily());assertEquals(java.util.Collections.singletonList(2L),MonthLedger.calculate(d,YearMonth.of(2026,10)).missingAccounts);}
    @Test public void midpointNoiseCannotChangeFinalExpense(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);long before=october(d).expense;MonthLedger.updateAccount(d,1,at("2026-10-10T10:00"),1100000);MonthLedger.updateAccount(d,1,at("2026-10-20T10:00"),200000);assertEquals(before,october(d).expense);assertFalse(october(d).anomaly);}
    @Test public void generatedIncomeAtMidnightBelongsOnlyToItsCalendarMonth(){Ledger.Data d=data();entry(d,Ledger.INCOME,200000,"2026-10-01T00:00",1,true);LedgerStore.validate(d);assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);assertEquals(0,october(d).expense);MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),1000000);LedgerStore.validate(d);assertEquals(200000,october(d).expense);}
    @Test public void generatedExpenseAtMidnightDoesNotLeakToPreviousMonth(){Ledger.Data d=data();entry(d,Ledger.LARGE,100000,"2026-10-01T00:00",1,true);LedgerStore.validate(d);assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);assertEquals(100000,october(d).expense);}
    @Test public void transferAtMidnightIsNeutralInBothMonths(){Ledger.Data d=data();TransferLedger.save(d,0,1,2,100000,at("2026-10-01T00:00"),"");LedgerStore.validate(d);assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);assertEquals(0,october(d).expense);}
    @Test public void nextMonthNewAccountDoesNotInvalidatePriorMonthBaseline(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),700000);Ledger.Account later=new Ledger.Account(3,"现金","现金");later.created=at("2026-11-01T00:00");later.opening=100;d.accounts.add(later);assertTrue(october(d).baseline);assertEquals(300000,october(d).expense);}
    @Test public void deletingOnlyOneTransferObservationKeepsSourceAndConservedTotal(){Ledger.Data d=data();Ledger.Transfer t=TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);AccountRecords.delete(d,1,t.at);LedgerStore.validate(d);assertEquals(1,d.transfers.size());assertEquals(900000,d.balance(d.accounts.get(0)));assertEquals(600000,d.balance(d.accounts.get(1)));assertEquals(1500000,d.total());assertFalse(row(d,"2026-10-05T15:00").balances.containsKey(1L));}
    @Test public void laterRealVerificationSurvivesTransferDeletion(){Ledger.Data d=data();Ledger.Transfer t=TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);MonthLedger.updateAccount(d,1,t.at,890000,"实测保留");d.transfers.clear();LedgerStore.validate(d);assertEquals(890000,d.balance(d.accounts.get(0)));assertEquals(500000,d.balance(d.accounts.get(1)));assertEquals("实测保留",row(d,"2026-10-05T15:00").notes.get(1L));}
    @Test public void notesAndSourcesUseStringKeysForAndroidJson()throws Exception{Ledger.Data d=data();TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"");LedgerStore.validate(d);JSONObject o=new JSONObject(LedgerStore.encode(d));JSONObject first=o.getJSONArray("snapshots").getJSONObject(0);assertEquals("用户手动更新余额",first.getJSONObject("notes").getString("1"));assertTrue(o.getJSONArray("snapshots").getJSONObject(1).getJSONObject("sources").has("1"));}
    @Test public void legacyImplicitOpeningKeepsSameInstantIncomeEffect(){Ledger.Data d=data();d.snapshots.clear();Ledger.Entry e=entry(d,Ledger.INCOME,200000,"2026-09-30T20:00",1,true);e.nearestCash=false;LedgerStore.validate(d);assertEquals(1200000,d.balance(d.accounts.get(0)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    @Test public void legacyImplicitOpeningKeepsSameInstantInvestmentDebit(){Ledger.Data d=data();d.snapshots.clear();Ledger.Fund f=FundTransactions.save(d,0,0,"006431",200000,0,at("2026-09-30T20:00"),null,"离线",false,true,1,new TradingCalendar());LedgerStore.validate(d);assertEquals(800000,d.balance(d.accounts.get(0)));assertTrue(f.buys.get(0).buyAccountLinked);assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    @Test public void expenseAtImplicitOpeningCountsAsConsumptionNotAnEmptyBaseline(){Ledger.Data d=data();d.snapshots.clear();entry(d,Ledger.LARGE,100000,"2026-09-30T20:00",1,true);LedgerStore.validate(d);assertEquals(900000,d.balance(d.accounts.get(0)));assertEquals(100000,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    @Test public void backupRoundTripPreservesTransfersNotesPoliciesAndOwnership()throws Exception{Ledger.Data d=data();TransferLedger.save(d,0,1,2,100000,at("2026-10-05T15:00"),"调配");entry(d,Ledger.LARGE,50000,"2026-10-10T10:00",1,true);LedgerStore.validate(d);String json=LedgerStore.encode(d);assertEquals(16,new JSONObject(json).getInt("version"));Ledger.Data restored=LedgerStore.decode(json);LedgerStore.validate(restored);assertEquals(json,LedgerStore.encode(restored));assertEquals("调配",restored.transfers.get(0).note);assertTrue(restored.entries.get(0).nearestCash);}
    @Test public void format15MissingNewFieldsDefaultsWithoutCreatingTransfers()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.put("version",15);o.remove("transfers");for(int i=0;i<o.getJSONArray("snapshots").length();i++){o.getJSONArray("snapshots").getJSONObject(i).remove("notes");o.getJSONArray("snapshots").getJSONObject(i).remove("sources");}Ledger.Data d=LedgerStore.decode(o.toString());LedgerStore.validate(d);assertTrue(d.transfers.isEmpty());assertEquals(1500000,d.total());}
    @Test(expected=IllegalArgumentException.class) public void malformedTransfersListRejected()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.put("transfers",new JSONObject());LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void malformedNotesRejected()throws Exception{JSONObject o=new JSONObject(LedgerStore.encode(data()));o.getJSONArray("snapshots").getJSONObject(0).put("notes",new JSONObject().put("1",false));LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void noteForMissingAccountCellRejected(){Ledger.Data d=data();d.snapshots.get(0).notes.put(99L,"无效账户备注");LedgerStore.validate(d);}
    @Test(expected=IllegalArgumentException.class) public void malformedPolicyRejected()throws Exception{Ledger.Data d=data();entry(d,Ledger.INCOME,1,"2026-10-01T10:00",0,false);JSONObject o=new JSONObject(LedgerStore.encode(d));o.getJSONArray("entries").getJSONObject(0).put("nearestCash","true");LedgerStore.decode(o.toString());}
    @Test(expected=IllegalArgumentException.class) public void fractionalTransferAmountRejected()throws Exception{Ledger.Data d=data();TransferLedger.save(d,0,1,2,1,at("2026-10-05T15:00"),"");JSONObject o=new JSONObject(LedgerStore.encode(d));o.getJSONArray("transfers").getJSONObject(0).put("amount",1.5);LedgerStore.decode(o.toString());}
}
